/**
 * **Delta** — a river delta seen from above, cut as an engraved survey map: a neatline with graduated border, valley
 * hachures at the top corners, a braided fan of distributaries (generated by splitting channels recursively from one
 * trunk), sandbars stippled between them, the sea hatched in shoreline echoes.
 *
 * Motion: it silts up. Every channel closes at its own time (the thin outer ones first, then the middle ones, then
 * the trunk): its banks pinch together, its water-lines drop out and sandbar dots gather along its course. At the end
 * one straight dredged canal — drawn on from the head to the sea — is all that is left. Red: that canal.
 */
import React from 'react';
import { CONTOUR, DETAIL, INNER, Plate, breathe, cut, ink } from '../engrave';
import { color } from '../tokens';

const rng = (seed: number) => {
  let s = seed >>> 0;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
};
const clamp = (x: number, a = 0, b = 1) => Math.max(a, Math.min(b, x));
const ss = (a: number, b: number, x: number) => { const t = clamp((x - a) / (b - a)); return t * t * (3 - 2 * t); };
const f1 = (n: number) => n.toFixed(1);

const coast = (x: number) => 352 - 46 * Math.pow(Math.min(1, Math.abs(x - 200) / 175), 1.3) + Math.sin(x * 0.11) * 2.5;

type Chan = { pts: [number, number][]; w: number; depth: number; siltT: number };

/** Recursive/iterative channel splitting: a branch wanders downhill and, now and then, divides in two. */
const buildNet = (): Chan[] => {
  const r = rng(2024);
  const out: Chan[] = [];
  type B = { x: number; y: number; a: number; w: number; depth: number; since: number; pts: [number, number][] };
  const q: B[] = [{ x: 200, y: 30, a: 0, w: 13, depth: 0, since: 0, pts: [[200, 30]] }];
  while (q.length && out.length < 90) {
    const b = q.shift()!;
    let done = false;
    for (let s = 0; s < 80 && !done; s++) {
      b.a += (r() - 0.5) * 0.2 - Math.sin(b.a) * 0.03;
      if (b.x < 56) b.a += 0.05;
      if (b.x > 344) b.a -= 0.05;
      b.a = clamp(b.a, -1.05, 1.05);
      const step = 9 + b.depth;
      b.x += Math.sin(b.a) * step; b.y += Math.cos(b.a) * step;
      b.pts.push([b.x, b.y]);
      b.since++;
      if (b.y >= coast(b.x) - 2 || b.x < 34 || b.x > 366) { done = true; break; }
      const canSplit = b.depth < 6 && b.since > (b.depth === 0 ? 5 : 3) && b.y > 56 && b.y < coast(b.x) - 28;
      if (canSplit && r() < (b.depth === 0 ? 0.6 : 0.34)) {
        const spread = 0.28 + r() * 0.3;
        for (const sg of [-1, 1]) q.push({ x: b.x, y: b.y, a: b.a + sg * spread, w: b.w * 0.72, depth: b.depth + 1, since: 0, pts: [[b.x, b.y]] });
        done = true;
      }
    }
    out.push({ pts: b.pts, w: b.w, depth: b.depth, siltT: 0 });
  }
  const r2 = rng(77);
  for (const ch of out) ch.siltT = clamp(0.06 + (7 - ch.depth) * 0.085 + r2() * 0.16 - (ch.depth === 0 ? 0.0 : 0), 0, 0.88);
  out[0].siltT = 0.8; // the trunk goes last
  return out;
};
const NET = buildNet();

const offsetPoly = (pts: [number, number][], half: (u: number) => number, side: number) =>
  pts.map(([x, y], i) => {
    const [x0, y0] = pts[Math.max(0, i - 1)], [x1, y1] = pts[Math.min(pts.length - 1, i + 1)];
    const dx = x1 - x0, dy = y1 - y0, L = Math.hypot(dx, dy) || 1;
    const h = half(i / Math.max(1, pts.length - 1)) * side;
    return [x + (-dy / L) * h, y + (dx / L) * h] as [number, number];
  });
const toPath = (p: [number, number][]) => p.map(([x, y], i) => `${i ? 'L' : 'M'}${f1(x)} ${f1(y)}`).join(' ');

export const Delta: React.FC<{ w: number; h: number; size?: number; at?: string | number; label?: string; labelAt?: string | number; plate?: string }> =
  ({ w, h, size, at, label, labelAt, plate }) => (
    <Plate w={w} h={h} size={size} label={label} labelAt={labelAt} at={at} plate={plate}>
      {(c) => {
        const t = c.at(30, 170);
        const state = NET.map((ch) => ({ ch, g: 1 - ss(ch.siltT, ch.siltT + 0.2, t) }));
        const alive = state.filter((s) => s.g > 0.05);

        // ---- channels: banks, water-lines ---------------------------------------------------------------
        const chans = state.map(({ ch, g }, i) => {
          if (g < 0.05) return null;
          const half = (u: number) => (ch.w * (1 - 0.22 * u) * 0.5) * g;
          const L = offsetPoly(ch.pts, half, 1), R = offsetPoly(ch.pts, half, -1);
          const bw = ch.depth < 2 ? INNER * 1.1 : DETAIL * 1.3;
          const flow: React.ReactNode[] = [];
          const nFlow = ch.w * g > 6 ? 3 : ch.w * g > 3 ? 2 : ch.w * g > 1.6 ? 1 : 0;
          for (let k = 0; k < nFlow; k++) {
            const off = nFlow === 1 ? 0 : (k / (nFlow - 1) - 0.5) * 1.1;
            const fl = offsetPoly(ch.pts, (u) => half(u) * off, 1);
            flow.push(<path key={k} d={toPath(fl)} {...cut(c.detail, color.ink, DETAIL * 0.8, k % 2 ? '9 4' : '16 3')} opacity={0.55} />);
          }
          return (
            <g key={i}>
              <path d={toPath(L)} {...cut(c.inner, color.ink, bw)} />
              <path d={toPath(R)} {...cut(c.inner, color.ink, bw)} />
              {flow}
              {/* river-mouth: the banks close with a short bar */}
            </g>
          );
        });

        // ---- sandbars: stipple clumps between the channels, gathering along the silting ones ---------------
        const rd = rng(404);
        const meanSilt = state.reduce((a, s) => a + (1 - s.g), 0) / state.length;
        const dots: React.ReactNode[] = [];
        for (let i = 0; i < 1500 && dots.length < 800; i++) {
          const x = 24 + rd() * 352, y = 70 + rd() * 290, pr = rd(), rr = 0.6 + rd() * 0.8;
          if (y > coast(x) + 6 || Math.abs(x - 200) > 40 + (y - 60) * 0.95) continue;
          let near = 1e9;
          for (const s of alive) for (const [px, py] of s.ch.pts) { const d = Math.hypot(px - x, py - y) - s.ch.w * 0.5 * s.g; if (d < near) near = d; }
          const patch = Math.sin(x * 0.09 + y * 0.04) * Math.sin(y * 0.11 - x * 0.05);
          const want = 0.4 + 0.5 * meanSilt + 0.3 * patch;
          if (near < 3 || pr > want) continue;
          dots.push(<circle key={i} cx={f1(x)} cy={f1(y)} r={f1(rr * 0.9)} />);
        }
        // silt gathering along each dying channel
        const silt: React.ReactNode[] = [];
        state.forEach(({ ch, g }, i) => {
          const s = 1 - g;
          if (s <= 0.02) return;
          const rs = rng(i * 13 + 5);
          ch.pts.forEach(([x, y], k) => {
            for (let m = 0; m < 3; m++) {
              if (rs() > s * 0.9) continue;
              const ox = (rs() - 0.5) * (ch.w * 1.1 + 2), oy = (rs() - 0.5) * 6;
              silt.push(<circle key={`${i}-${k}-${m}`} cx={f1(x + ox)} cy={f1(y + oy)} r={f1(0.6 + rs() * 0.8)} />);
            }
          });
        });

        // ---- shoreline echoes in the sea -------------------------------------------------------------------
        const sea = [0, 1, 2, 3, 4, 5, 6].map((k) => {
          let d = '';
          for (let i = 0; i <= 50; i++) { const x = 28 + (344 * i) / 50; d += `${i ? 'L' : 'M'}${f1(x)} ${f1(coast(x) + 7 + k * 6 + Math.sin(x * 0.2 + k) * 1.2)} `; }
          return <path key={k} d={d} {...cut(c.shade, color.ink, k < 2 ? DETAIL * 1.1 : DETAIL * 0.8, k % 2 ? '12 5 3 5' : '22 6')} opacity={Math.max(0.15, 0.7 - k * 0.09)} />;
        });
        const shore = (() => { let d = ''; for (let i = 0; i <= 60; i++) { const x = 24 + (352 * i) / 60; d += `${i ? 'L' : 'M'}${f1(x)} ${f1(coast(x))} `; } return d; })();

        // ---- valley hachures, top corners -----------------------------------------------------------------
        const rh = rng(9);
        const hach: string[] = [];
        for (let y = 30; y < 200; y += 6.5) {
          for (const side of [-1, 1]) {
            const edge = 200 + side * (46 + (y - 30) * 0.2) , n = 3 + Math.floor((200 - y) / 70);
            for (let k = 0; k < n; k++) {
              const x = edge + side * (k * 11 + rh() * 5), len = 4 + rh() * 6;
              if (x < 26 || x > 374) continue;
              hach.push(`M${f1(x)} ${f1(y)} l${f1(side * len)} ${f1(len * 0.6)}`);
            }
          }
        }
        // graduated neatline ticks
        const ticks: string[] = [];
        for (let k = 0; k <= 16; k++) { const p = 20 + k * 22.5; ticks.push(`M${p} 14 V20 M${p} 380 V386 M14 ${p} H20 M380 ${p} H386`); }

        // ---- the dredged canal ------------------------------------------------------------------------------
        const cp = c.at(54, 70);
        const canalEnd = coast(200) + 4;
        const cy = 30 + (canalEnd - 30) * cp;

        return (
          <g style={breathe(c.frame, 1.0, 220)}>
            <path d={`M14 14 H386 V386 H14 Z`} {...cut(c.contour, color.ink, CONTOUR * 0.7)} />
            <path d={`M20 20 H380 V380 H20 Z`} {...cut(c.inner, color.ink, DETAIL)} />
            <path d={ticks.join(' ')} {...cut(c.detail, color.ink, DETAIL)} />
            <path d={hach.join(' ')} {...cut(c.detail, color.ink, DETAIL)} opacity={0.55} />
            {sea}
            <path d={shore} {...cut(c.contour, color.ink, INNER * 1.1)} />
            <g fill={color.ink} opacity={0.5 * c.detail}>{dots}</g>
            <g fill={color.ink} opacity={0.55 * c.detail}>{silt}</g>
            {chans}
            {/* the canal: straight, embanked on both sides, red water-line down the middle */}
            <path d={`M193 30 V${f1(cy)} M207 30 V${f1(cy)}`} {...cut(c.inner * (cp > 0 ? 1 : 0), color.ink, INNER)} />
            <path d={`M200 30 V${f1(cy)}`} {...cut(cp > 0 ? 1 : 0, color.red, INNER * 1.5)} />
            <path d={`M188 ${f1(cy)} h-8 M212 ${f1(cy)} h8`} {...cut(cp > 0.9 ? 1 : 0, color.ink, DETAIL)} />
            <circle cx={200} cy={30} r={5} {...ink(c.accent, color.red)} />
            {/* spoil heaps along the dredged cut */}
            <path d={Array.from({ length: 14 }, (_, i) => `M${i % 2 ? 214 : 186} ${f1(44 + i * 20)} l${i % 2 ? 6 : -6} ${i % 2 ? 4 : -4}`).join(' ')} {...cut(cp, color.ink, DETAIL)} opacity={0.6} />
          </g>
        );
      }}
    </Plate>
  );
